    private static let b1: [Double] = [-0.281043785, -0.365241935, -0.334308238, -0.255736803, -0.116790953, 0.511020405, -0.035385325, -0.0429854895, 0.0669478399, 0.197211923, 0.30574953, -0.230436922, 0.0588495282, 0.280481037, 0.253834423, 0.456663203]
    private static let w2: [[Double]] = [
        [-0.715693817, 0.796013293, 0.595954108, 0.95723898, 0.581056485, -0.407982383, 0.983977466, -0.552627355, -0.410621055, -0.892959476, -0.797976012, 0.72073618, 0.513447313, -0.777928701, -0.839164199, -0.681772703]
    ]
    private static let b2: [Double] = [-0.306793221]
    private static func layer(_ input: [Double], _ weights: [[Double]], _ bias: [Double], hidden: Bool) -> [Double] {
        weights.indices.map { row in
            var value = bias[row]
            for i in input.indices { value += weights[row][i] * input[i] }
            return hidden ? tanh(value) : 1 / (1 + exp(-max(-30,min(30,value))))
        }
    }
    static func predict(_ features: [Double]) -> Double {
        guard features.count == 16, features.allSatisfy({ $0.isFinite }) else { return 0 }
        let first = layer(features,w0,b0,hidden:true)
        let second = layer(first,w1,b1,hidden:true)
        return layer(second,w2,b2,hidden:false)[0]
    }
}
